import{_ as t,a,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"第二册：实践与进步 · Lesson 37 The Olympic Games","description":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 37 The Olympic Games","description":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 36 Across the Channel","link":"/life/english/new-concept/book-2/unit-02/lesson-036"},"next":{"text":"第二册：实践与进步 · Lesson 38 Everything except the weather","link":"/life/english/new-concept/book-2/unit-02/lesson-038"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 36 Across the Channel","link":"/life/english/new-concept/book-2/unit-02/lesson-036"},"next":{"text":"第二册：实践与进步 · Lesson 38 Everything except the weather","link":"/life/english/new-concept/book-2/unit-02/lesson-038"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/lesson-037.md","filePath":"life/english/new-concept/book-2/unit-02/lesson-037.md"}'),l={name:"life/english/new-concept/book-2/unit-02/lesson-037.md"};function o(r,e,s,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第二册-实践与进步-·-lesson-37-the-olympic-games" tabindex="-1">第二册：实践与进步 · Lesson 37 The Olympic Games <a class="header-anchor" href="#第二册-实践与进步-·-lesson-37-the-olympic-games" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 37 The Olympic Games&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>筹备大型赛事要交代设施建设与开放时间，不能把规划当成完工；练习将来被动。本课的语言观察是：will be opened 表未来开放事件；is being built 表当前施工。两种被动可在同一工程说明中分别交代现在与将来。完成学习后，请写三句设施进度公告，分别写当前测试、开放月份和首场活动。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>stadium</td><td>/ˈsteɪdiəm/</td><td>n.</td><td>体育场</td><td>a new stadium</td></tr><tr><td>event</td><td>/ɪˈvent/</td><td>n.</td><td>赛事；事件</td><td>a sporting event</td></tr><tr><td>build</td><td>/bɪld/</td><td>v.</td><td>建造</td><td>build a bridge</td></tr><tr><td>athlete</td><td>/ˈæθliːt/</td><td>n.</td><td>运动员</td><td>a young athlete</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>take place — 发生、举行，不用被动语态</li><li>be ready for — 为……准备就绪</li></ul><h2 id="语法讲解-被动语态与信息重点" tabindex="-1">语法讲解：被动语态与信息重点 <a class="header-anchor" href="#语法讲解-被动语态与信息重点" aria-label="Permalink to &quot;语法讲解：被动语态与信息重点&quot;">​</a></h2><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：will be opened 表未来开放事件；is being built 表当前施工。两种被动可在同一工程说明中分别交代现在与将来。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The new stadium will be opened in September.</p></blockquote><p>新体育场将在九月开放。</p><p>stadium 是被开放的设施，will be opened 为将来被动，in September 表月份。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>The event will be taken place 错误；take place 本身是不及物表达。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对照 opened 与 October，注意 opened 为两音节，词尾 /d/ 不另成一节。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The new stadium will be opened in September. Workers are testing the lights this week. The first event will take place in October.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句设施进度公告，分别写当前测试、开放月份和首场活动。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：stadium 是被开放的设施，will be opened 为将来被动，in September 表月份。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：The event will be taken place 错误；take place 本身是不及物表达。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>补全：The stadium will ___ opened in September.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> be</p><p><strong>解析：</strong> will 后用 be 原形，再加过去分词 opened。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>首场赛事在哪个月举行？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> In October.</p><p><strong>解析：</strong> 开放在九月，首场活动在十月，不能混淆。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>改正：The race will be taken place here。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The race will take place here.</p><p><strong>解析：</strong> take place 不构成常规被动。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：被动语态与信息重点。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-036">上一课</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-038">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const u=t(l,[["render",o]]);export{b as __pageData,u as default};
